from pathlib import Path
import re, subprocess
q=Path("scripts/wull-fixtures/presence/WullPresencePreview.qml")
orig=q.read_text()
needle='''    function require(value,message): void {
        if (!value) {console.error("WULL_PRESENCE_CHECK=FAIL "+message);Qt.quit();throw new Error(message)}
    }'''
inst='''    property int diagnosticCheckIndex: 0
    function require(value,message): void {
        diagnosticCheckIndex++
        if (!value) {console.error("WULL_PRESENCE_CHECK=FAIL_"+diagnosticCheckIndex);Qt.quit();throw new Error(message)}
    }'''
if needle not in orig:
    raise SystemExit(11)
q.write_text(orig.replace(needle,inst))
out=""
rc=1
try:
    try:
        p=subprocess.run(["python3","scripts/test-wull-presence-interaction.py"],stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,timeout=105)
        out=p.stdout or ""
        rc=p.returncode
    except subprocess.TimeoutExpired as e:
        out=(e.stdout or "") if isinstance(e.stdout,str) else ""
        raise SystemExit(91)
finally:
    q.write_text(orig)
if rc==0:
    raise SystemExit(0)
m=re.search(r"WULL_PRESENCE_CHECK=FAIL_(\d+)",out)
if m:
    raise SystemExit(20+int(m.group(1)))
for code,marker in [
    (80,"ReferenceError:"),(81,"TypeError:"),(82,"SyntaxError:"),
    (83,"Unable to assign"),(84,"Binding loop"),(85,"non-root animation nodes"),
    (86,"Failed to load configuration")]:
    if marker in out:
        raise SystemExit(code)
if "WULL_PRESENCE_CHECK=PASS" in out:
    raise SystemExit(88)
raise SystemExit(90)
